def volume_to_index(volume, A):
    index = 0
    for s in volume:
        index = index * A + s
    return index

def index_to_volume(index, A, L):
    volume = []
    for _ in range(L):
        volume.append(index % A)
        index //= A
    return volume[::-1]

import math
def sphere_size(A, L, r):
    return math.comb(L, r) * (A - 1) ** r

def de_bruijn(A, L):
    seq = []
    a = [0] * (A * L)
    def db(t, p):
        if t > L:
            if L % p == 0:
                seq.extend(a[1:p+1])
        else:
            a[t] = a[t-p]
            db(t+1, p)
            for j in range(a[t-p]+1, A):
                a[t] = j
                db(t+1, t)
    db(1, 1)
    return seq
